-- Disposable schema only. Helpers do not commit; fixtures and result-table inserts roll back.
-- The runner preserves emitted results outside the fixture transaction.
SET SESSION sql_mode='STRICT_TRANS_TABLES,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION';
START TRANSACTION;
INSERT INTO Branches(branch_name,ifsc_code,address,city,state,phone) VALUES('Synthetic branch','TEST-IFSC-A','Synthetic address','Test city','Test state','0000000000');
SET @branch=LAST_INSERT_ID();
INSERT INTO Employees(branch_id,full_name,role,email,hire_date) VALUES(@branch,'Synthetic teller','Teller','teller.fixture@example.invalid','2020-01-01');
SET @employee=LAST_INSERT_ID();
INSERT INTO Customers(full_name,dob,email,phone,address,id_proof_number,id_proof_type) VALUES('Synthetic customer','1990-01-01','customer.fixture@example.invalid','0000000001','Synthetic address','SYNTHETIC-ID-A','Passport');
SET @customer=LAST_INSERT_ID();
INSERT INTO Account_Types(type_name,interest_rate,min_balance) VALUES('Synthetic type',2.00,0.00);
SET @type=LAST_INSERT_ID();
INSERT INTO Accounts(customer_id,branch_id,account_type_id,account_number,balance,opened_date) VALUES(@customer,@branch,@type,'SYNTHETIC-ACCT-A',100.00,'2026-01-01');
SET @account=LAST_INSERT_ID();
INSERT INTO Transactions(account_id,transaction_type,amount,balance_after,channel,status,reference_no) VALUES(@account,'Deposit',100,100,'Online','Completed','SYNTHETIC-OPENING-A');
SET @txn=LAST_INSERT_ID();
INSERT INTO Transactions(account_id,transfer_group_id,transaction_type,amount,balance_after,channel,status,reference_no) VALUES(@account,'00000000-0000-0000-0000-000000000001','TransferOut',1,99,'Online','Pending','SYNTHETIC-GROUP-A');
INSERT INTO Fraud_Rules(rule_code,weight) VALUES('SYNTHETIC_RULE_A',1);
SET @rule=LAST_INSERT_ID();
INSERT INTO Fraud_Flags(transaction_id,rule_id,risk_score) VALUES(@txn,@rule,10);
CALL bank_lab.sp_expect_error(DATABASE(),'duplicate customer email','INSERT INTO {db}.Customers(full_name,dob,email,phone,address,id_proof_number,id_proof_type) VALUES(''Synthetic'',''1990-01-01'',''customer.fixture@example.invalid'',''0000000002'',''Synthetic'',''SYNTHETIC-ID-B'',''Passport'')',1062);
